//! `binds:` on a fixture op: the macro derives the binding, and the verifier
//! holds every aligned range to one length and one type per offset.

use tir::{
    Binding, Context, Gamma, Operation, RegionId, Theta, TypeId, ValueId,
    builtin::{self, ops},
};

tir::helpers::operation! {
    ThetaOp {
        name: "theta",
        dialect: "test",
        scheme: "(_*) -> _*",
        operands: O { inits },
        results: R { results },
        regions: R {
            body: Region {
                kind: Nodes,
            }
        },
        binds: Theta {
            carried: inits ~ body.ports ~ body.results[1..n+1] ~ body.results[n+1..] ~ results,
            predicate: body.results[0],
        },
    }
}

tir::helpers::operation! {
    GammaOp {
        name: "gamma",
        dialect: "test",
        scheme: "(int<_>, _*) -> _*",
        operands: O { predicate, inputs },
        results: R { results },
        regions: R {
            arms: Region {
                kind: Nodes,
                variadic: true,
            }
        },
        binds: Gamma {
            predicate,
            forwarded: inputs ~ arms.ports,
            joined: arms.results ~ results,
        },
    }
}

fn nodes_region(context: &Context, port_types: &[TypeId], results: &[(i64, u32)]) -> RegionId {
    let ports = port_types
        .iter()
        .map(|&ty| context.create_value(ty, None))
        .collect();
    let constants: Vec<_> = results
        .iter()
        .map(|&(value, width)| {
            ops::constant(
                context,
                value,
                builtin::IntegerType::new(context, u64::from(width)),
                Default::default(),
                tir::InsertionPoint::Root,
            )
        })
        .collect();
    let values: Vec<ValueId> = constants.iter().map(|c| c.value_results()[0]).collect();
    let op_ids = constants.iter().map(|c| c.id()).collect();
    context.create_nodes_region(ports, op_ids, values).id()
}

fn build_theta(context: &Context, port_types: &[TypeId], results: &[(i64, u32)]) -> tir::OpHandle {
    let i32_ty = builtin::IntegerType::new(context, 32);
    let init = ops::constant(
        context,
        7,
        i32_ty,
        Default::default(),
        tir::InsertionPoint::Root,
    );
    r#theta(
        context,
        vec![init.value_results()[0]],
        vec![i32_ty],
        Some(nodes_region(context, port_types, results)),
        Default::default(),
        tir::InsertionPoint::Root,
    )
}

#[test]
fn a_theta_binding_aligns_inits_ports_continue_exit_and_results() {
    let context = Context::with_default_dialects();
    let i32_ty = builtin::IntegerType::new(&context, 32);
    let op = build_theta(&context, &[i32_ty], &[(1, 1), (2, 32), (3, 32)]);

    let theta = op
        .clone()
        .as_interface::<dyn Theta>()
        .expect("theta interface");
    assert_eq!(
        theta.binding(),
        Binding {
            operands: 0..1,
            ports: 0..1,
            continue_: 1..2,
            exit: 2..3,
            results: 0..1,
        }
    );
    let body = context.get_region(theta.body());
    assert_eq!(theta.predicate(), body.value_results()[0]);
    op.verify(&context).expect("an aligned theta verifies");
}

#[test]
fn a_theta_port_must_have_its_init_type() {
    let context = Context::with_default_dialects();
    let i64_ty = builtin::IntegerType::new(&context, 64);
    let op = build_theta(&context, &[i64_ty], &[(1, 1), (2, 32), (3, 32)]);

    let error = op
        .verify(&context)
        .expect_err("the port is wider than its init");
    assert!(error.to_string().contains("port"), "{error}");
}

fn build_gamma(context: &Context, arm_results: &[&[(i64, u32)]]) -> tir::OpHandle {
    let i32_ty = builtin::IntegerType::new(context, 32);
    let predicate = ops::constant(
        context,
        0,
        i32_ty,
        Default::default(),
        tir::InsertionPoint::Root,
    );
    let input = ops::constant(
        context,
        5,
        i32_ty,
        Default::default(),
        tir::InsertionPoint::Root,
    );
    let arms = arm_results
        .iter()
        .map(|results| nodes_region(context, &[i32_ty], results))
        .collect();
    r#gamma(
        context,
        predicate.value_results()[0],
        vec![input.value_results()[0]],
        vec![i32_ty],
        arms,
        Default::default(),
        tir::InsertionPoint::Root,
    )
}

#[test]
fn a_gamma_binding_forwards_inputs_and_joins_arm_results() {
    let context = Context::with_default_dialects();
    let op = build_gamma(&context, &[&[(1, 32)], &[(2, 32)]]);

    let gamma = op
        .clone()
        .as_interface::<dyn Gamma>()
        .expect("gamma interface");
    assert_eq!(
        gamma.binding(),
        Binding {
            operands: 1..2,
            ports: 0..1,
            continue_: 0..0,
            exit: 0..1,
            results: 0..1,
        }
    );
    assert_eq!(gamma.arms().len(), 2);
    assert_eq!(gamma.predicate(), op.operands()[0]);
    op.verify(&context).expect("an aligned gamma verifies");
}

fn counted(
    context: &Context,
    predicate: tir::attributes::Predicate,
    shape: impl Fn(&[ValueId; 5]) -> Vec<ValueId>,
) -> tir::OpHandle {
    let i32_ty = builtin::IntegerType::new(context, 32);
    let i1 = builtin::IntegerType::new(context, 1);
    let bounds: Vec<ValueId> = [0, 10, 1, 7]
        .iter()
        .map(|&value| {
            ops::constant(
                context,
                value,
                i32_ty,
                Default::default(),
                tir::InsertionPoint::Root,
            )
            .value_results()[0]
        })
        .collect();
    let counter = context.create_value(i32_ty, None);
    let carried = context.create_value(i32_ty, None);
    let compare = tir::builtin::r#cmpi(
        context,
        counter.id(),
        bounds[1],
        tir::attributes::AttributeValue::Predicate(predicate),
        i1,
        Default::default(),
        tir::InsertionPoint::Root,
    );
    let advance = tir::builtin::r#addi(
        context,
        counter.id(),
        bounds[2],
        i32_ty,
        Default::default(),
        tir::InsertionPoint::Root,
    );
    let doubled = ops::addi(
        context,
        carried.id(),
        carried.id(),
        i32_ty,
        Default::default(),
        tir::InsertionPoint::Root,
    );
    let results = shape(&[
        counter.id(),
        compare.value_results()[0],
        advance.value_results()[0],
        carried.id(),
        doubled.value_results()[0],
    ]);
    let body = context.create_nodes_region(
        vec![counter, carried],
        vec![compare.id(), advance.id(), doubled.id()],
        results,
    );
    tir::scf::r#for(
        context,
        bounds[0],
        vec![bounds[3]],
        bounds[1],
        bounds[2],
        vec![i32_ty, i32_ty],
        Some(body.id()),
        Default::default(),
        tir::InsertionPoint::Root,
    )
}

#[test]
fn a_loop_names_each_carried_value_on_every_side() {
    let context = Context::with_default_dialects();
    let op = counted(
        &context,
        tir::attributes::Predicate::Slt,
        |[i, cmp, next, a, doubled]| vec![*cmp, *next, *doubled, *i, *a],
    );
    let handle = &op;
    let body = context.get_region(
        op.clone()
            .as_interface::<dyn Theta>()
            .expect("for is theta")
            .body(),
    );
    let (ports, results) = (body.ports(), body.results());

    let carried = tir::binding::carried(&context, handle);

    let side = |index: usize| tir::binding::Carried {
        init: handle.operands()[index],
        port: ports[index].id(),
        next: results[1 + index],
        exit: results[3 + index],
        result: handle.results()[index],
    };
    assert_eq!(carried, vec![side(0), side(1)]);
}

#[test]
fn a_counted_loop_pins_its_comparison_increment_and_exits() {
    let context = Context::with_default_dialects();
    let op = counted(
        &context,
        tir::attributes::Predicate::Slt,
        |[i, cmp, next, a, doubled]| vec![*cmp, *next, *doubled, *i, *a],
    );

    op.verify(&context).expect("the pinned shape verifies");
    assert_eq!(
        op.as_interface::<dyn tir::CountedLoop>()
            .expect("for is counted")
            .induction(),
        Some(0)
    );
}

fn counted_error(
    predicate: tir::attributes::Predicate,
    shape: impl Fn(&[ValueId; 5]) -> Vec<ValueId>,
) -> String {
    let context = Context::with_default_dialects();
    let op = counted(&context, predicate, shape);
    op.verify(&context)
        .expect_err("the loop is not counted")
        .to_string()
}

#[test]
fn a_counted_loop_compares_signed_less_than() {
    let error = counted_error(
        tir::attributes::Predicate::Sgt,
        |[i, cmp, next, a, doubled]| vec![*cmp, *next, *doubled, *i, *a],
    );
    assert!(error.contains("cmpi slt"), "{error}");
}

#[test]
fn a_counted_loop_advances_its_counter_by_the_step() {
    let error = counted_error(
        tir::attributes::Predicate::Slt,
        |[i, cmp, _, a, doubled]| vec![*cmp, *doubled, *doubled, *i, *a],
    );
    assert!(error.contains("advance"), "{error}");
}

#[test]
fn a_counted_loop_leaves_every_port_unchanged() {
    let error = counted_error(
        tir::attributes::Predicate::Slt,
        |[i, cmp, next, _, doubled]| vec![*cmp, *next, *doubled, *i, *doubled],
    );
    assert!(error.contains("exit value 1 must be port 1"), "{error}");
}

//! Placement-free edits on unordered regions: growing declared ports and
//! placing an op by its operands.

use tir::{
    Context, ExitTarget, NonLocalExit, OpId, Operation, RegionId, Terminator, ValueId,
    builtin::{self, ops},
    interp,
};

use super::fixtures::{self, module_ops};

fn function(context: &Context, module: &tir::OpHandle) -> OpId {
    module_ops(context, module.id())[0]
}

fn body_of(context: &Context, function: OpId) -> RegionId {
    context.get_op(function).regions()[0]
}

fn find(context: &Context, region: RegionId, descriptor: &tir::OpDefSpec) -> OpId {
    context
        .get_region(region)
        .op_ids()
        .into_iter()
        .find(|&op| context.get_op(op).is_operation(descriptor))
        .expect("the region holds the op")
}

fn run(context: &Context, function: OpId, args: &[i64]) -> i64 {
    let args = args
        .iter()
        .map(|&value| interp::Value::Int(tir::utils::APInt::new_signed(32, value)))
        .collect();
    interp::run_function(context, function, args).expect("runs")[0]
        .to_i64()
        .expect("an integer")
}

const LOOP: &str = r#"module {
  %fn_main = func.func @main(%0: !i32) -> !i32 {
    %1 = constant {value = 0} : !i1
    %2 = scf.loop (%3 = %0) {
      -> %1, %3, %3
    }
    -> %2
  }
  module_end
}"#;

#[test]
fn growing_a_loop_port_extends_every_aligned_range() {
    let (context, module) = fixtures::parse(LOOP);
    let function = function(&context, &module);
    let body = body_of(&context, function);
    let loop_op = find(&context, body, &tir::scf::LOOP);
    let init = context.get_region(body).ports()[0].id();
    let i32_ty = builtin::IntegerType::new(&context, 32);

    let mut carried = None;
    let result = context.grow_port(loop_op, i32_ty, Some(init), |_, port| {
        carried = port;
        port
    });

    let grown = context.get_op(loop_op);
    let loop_body = context.get_region(grown.regions()[0]);
    assert_eq!(grown.value_operands().as_slice(), [init, init]);
    assert_eq!(loop_body.value_arguments().len(), 2);
    assert_eq!(loop_body.value_arguments()[1].id(), carried.unwrap());
    assert_eq!(loop_body.value_arguments()[1].ty(), i32_ty);
    let results = loop_body.value_results();
    assert_eq!(results.len(), 5, "predicate, two continue, two exit");
    assert_eq!(results[2], carried.unwrap(), "the port continues as itself");
    assert_eq!(
        results[4],
        carried.unwrap(),
        "the exit value defaults to the port"
    );
    assert_eq!(
        grown.value_results().as_slice(),
        [grown.value_results()[0], result]
    );
    tir::verify_op_tree(&context, module.id()).expect("the grown loop verifies");
}

#[test]
fn growing_a_loop_state_port_keeps_the_carried_shape() {
    let (context, module) = fixtures::parse(LOOP);
    let function = function(&context, &module);
    let body = body_of(&context, function);
    let loop_op = find(&context, body, &tir::scf::LOOP);
    let entry = tir::state::r#entry_state(
        &context,
        vec![tir::builtin::StateType::memory(&context)],
        Default::default(),
        tir::InsertionPoint::Root,
    );
    context.insert(tir::InsertionPoint::Region(body), entry.id());
    let chain = entry.state_results()[0];

    let state_type = context.get_value(chain).ty();
    let result = context.grow_port(loop_op, state_type, Some(chain), |_, port| port);

    let grown = context.get_op(loop_op);
    let loop_body = context.get_region(grown.regions()[0]);
    assert_eq!(grown.state_operands().as_slice(), [chain]);
    assert_eq!(loop_body.state_arguments().len(), 1);
    assert_eq!(loop_body.state_results().len(), 2);
    assert_eq!(grown.state_results().as_slice(), [result]);
    assert_eq!(
        loop_body.value_results().len(),
        3,
        "the value ranges are untouched"
    );
    tir::verify_op_tree(&context, module.id()).expect("the grown loop verifies");
}

const SWITCH: &str = r#"module {
  %fn_main = func.func @main(%0: !i32, %1: !i32) -> !i32 {
    scf.switch %0 {
      ->
    }
    {
      ->
    }
    -> %1
  }
  module_end
}"#;

#[test]
fn growing_a_gamma_port_forwards_to_and_joins_every_arm() {
    let (context, module) = fixtures::parse(SWITCH);
    let function = function(&context, &module);
    let body = body_of(&context, function);
    let switch = find(&context, body, &tir::scf::SWITCH);
    let input = context.get_region(body).ports()[1].id();
    let i32_ty = builtin::IntegerType::new(&context, 32);

    let result = context.grow_port(switch, i32_ty, Some(input), |_, port| port);

    let grown = context.get_op(switch);
    assert_eq!(
        grown.value_operands().as_slice(),
        [context.get_region(body).ports()[0].id(), input]
    );
    for arm in grown.regions() {
        let arm = context.get_region(arm);
        assert_eq!(arm.value_arguments().len(), 1);
        assert_eq!(arm.value_results(), vec![arm.value_arguments()[0].id()]);
    }
    assert_eq!(grown.value_results().as_slice(), [result]);
    tir::verify_op_tree(&context, module.id()).expect("the grown gamma verifies");
}

tir::helpers::operation! {
    ExitOp {
        print_hook: exit_custom_print,
        parse_hook: |parser, context, _definition| exit_custom_parse(parser, context),
        interface_callbacks: [(NonLocalExit, &tir::NonLocalExitCallbacks {
            target: |_| ExitTarget::InnermostLoop,
            values: |operation| operation.operands().to_vec(),
        })],
        name: "exit",
        dialect: "test",
        scheme: "(_*) -> ()",
        format: "custom",
        operands: O { values },
        interfaces: [Terminator, NonLocalExit],
    }
}

fn exit_custom_print(
    _operation: &tir::OpHandle,
    fmt: &mut tir::IRFormatter,
) -> Result<(), std::fmt::Error> {
    fmt.write("test.exit\n")
}

fn exit_custom_parse(
    _parser: &mut tir::parse::text::Parser,
    context: &Context,
) -> Result<tir::OpHandle, (tir::parse::Span, tir::Error)> {
    Ok(r#exit(
        context,
        vec![],
        Default::default(),
        tir::InsertionPoint::Root,
    ))
}

fn loop_with_exit() -> (Context, OpId, OpId) {
    let (context, module) = fixtures::parse(LOOP);
    context.register_operation(&EXIT);
    let function = function(&context, &module);
    let loop_op = find(&context, body_of(&context, function), &tir::scf::LOOP);
    let body = context.get_op(loop_op).regions()[0];
    let predicate = context.get_region(body).results()[0];
    let exit = r#exit(
        &context,
        vec![],
        Default::default(),
        tir::InsertionPoint::Root,
    );
    let arm = |ops: Vec<OpId>| context.create_nodes_region(vec![], ops, vec![]).id();
    let conditional = tir::scf::r#switch(
        &context,
        predicate,
        vec![],
        vec![],
        vec![arm(vec![]), arm(vec![exit.id()])],
        Default::default(),
        tir::InsertionPoint::Root,
    );
    context.insert(tir::InsertionPoint::Region(body), conditional.id());
    (context, loop_op, exit.id())
}

#[test]
fn a_non_local_exit_leaving_the_loop_resolves_to_it() {
    let (context, loop_op, exit) = loop_with_exit();

    assert_eq!(
        tir::analysis::exits::resolve_exit_target(&context, exit).ok(),
        Some(loop_op)
    );
}

#[test]
fn growing_a_loop_port_feeds_the_exits_leaving_it() {
    let (context, loop_op, exit) = loop_with_exit();
    let i32_ty = builtin::IntegerType::new(&context, 32);
    let init = context.get_op(loop_op).value_operands()[0];

    context.grow_port(loop_op, i32_ty, Some(init), |_, port| port);

    let port = context
        .get_region(context.get_op(loop_op).regions()[0])
        .value_arguments()[1]
        .id();
    assert_eq!(context.get_op(exit).operands().as_slice(), [port]);
}

const NESTED: &str = r#"module {
  %fn_main = func.func @main(%0: !i32) -> !i32 {
    %1 = constant {value = 0} : !i1
    %2 = scf.loop (%3 = %0) {
      %4 = addi %3, %0 : !i32
      -> %1, %4, %3
    }
    -> %2
  }
  module_end
}"#;

#[test]
fn add_auto_places_an_op_where_its_operands_meet() {
    let (context, module) = fixtures::parse(NESTED);
    let function = function(&context, &module);
    let outer = body_of(&context, function);
    let inner = context
        .get_op(find(&context, outer, &tir::scf::LOOP))
        .regions()[0];
    let argument = context.get_region(outer).ports()[0].id();
    let port = context.get_region(inner).ports()[0].id();
    let i32_ty = builtin::IntegerType::new(&context, 32);

    let mixed = ops::addi(
        &context,
        port,
        argument,
        i32_ty,
        Default::default(),
        tir::InsertionPoint::Root,
    );
    let outside = ops::addi(
        &context,
        argument,
        argument,
        i32_ty,
        Default::default(),
        tir::InsertionPoint::Root,
    );

    assert_eq!(context.add_auto(mixed.id()), inner);
    assert_eq!(context.add_auto(outside.id()), outer);
    assert_eq!(context.parent_nodes_region(mixed.id()), Some(inner));
}

#[test]
fn add_auto_pins_an_op_to_its_state() {
    let (context, module) = fixtures::parse(NESTED);
    let function = function(&context, &module);
    let outer = body_of(&context, function);
    let loop_op = find(&context, outer, &tir::scf::LOOP);
    let chain = context.grow_port(
        loop_op,
        tir::builtin::StateType::memory(&context),
        Some(
            context
                .create_value(tir::builtin::StateType::memory(&context), None)
                .id(),
        ),
        |_, port| port,
    );
    let inner = context.get_op(loop_op).regions()[0];
    let inner_chain = context.get_region(inner).state_arguments()[0].id();
    let argument = context.get_region(outer).ports()[0].id();
    let i32_ty = builtin::IntegerType::new(&context, 32);

    let pinned_out = ops::addi(
        &context,
        argument,
        argument,
        i32_ty,
        Default::default(),
        tir::InsertionPoint::Root,
    );
    context.append_operand(pinned_out.id(), chain);
    let pinned_in = ops::addi(
        &context,
        argument,
        argument,
        i32_ty,
        Default::default(),
        tir::InsertionPoint::Root,
    );
    context.append_operand(pinned_in.id(), inner_chain);

    assert_eq!(context.add_auto(pinned_out.id()), outer);
    assert_eq!(context.add_auto(pinned_in.id()), inner);
}

const COUNTED: &str = r#"module {
  %fn_main = func.func @main(%0: !i32, %1: !i32, %2: !i32) -> !i32 {
    %3 = scf.for %4 = %0 to %1 step %2 {
      ->
    }
    -> %3
  }
  module_end
}"#;

#[test]
fn growing_a_counted_loop_port_lands_before_its_bounds() {
    let (context, module) = fixtures::parse(COUNTED);
    let function = function(&context, &module);
    let body = body_of(&context, function);
    let for_op = find(&context, body, &tir::scf::FOR);
    let ports = context.get_region(body).ports();
    let (lb, ub, step) = (ports[0].id(), ports[1].id(), ports[2].id());
    let i32_ty = builtin::IntegerType::new(&context, 32);

    let result = context.grow_port(for_op, i32_ty, Some(ub), |_, port| port);

    let grown = context.get_op(for_op);
    assert_eq!(grown.value_operands().as_slice(), [lb, ub, ub, step]);
    assert_eq!(grown.value_results().len(), 2);
    assert_eq!(grown.value_results()[1], result);
    tir::verify_op_tree(&context, module.id()).expect("the grown counted loop verifies");
    assert_eq!(run(&context, function, &[0, 3, 1]), 3);
}

//! The one register notation: register slots as SSA ports, physical literals,
//! the assignment map, and the rules the machine-IR verifier enforces over them.
//!
//! Machine instructions have no textual form, so these build the IR directly
//! rather than through a `.tir` check.

use tir::attributes::AttributeValue;
use tir::backend::regalloc::RegClassId;
use tir::backend::{
    ASSIGNMENT_ATTR, PINS_ATTR, RegAssignment, RegClassType, phys_attr, verify_machine_ir,
};
use tir::{Context, Operation, ValueId};

use super::fixtures::{asm_symbol, r, r_high};

// `add rd, rs`: one destination slot and one source slot, both of class `R`,
// plus the implicit flag register the behavior writes.

static ADD_IMPLICIT: [tir::attributes::ImplicitReg; 1] = [tir::attributes::ImplicitReg {
    class: r(),
    index: 7,
    role: tir::attributes::AttributeRole::Def,
}];

tir::operation! {
    AddTestOp {
        name: "add", dialect: "test", scheme: "(_?) -> _?",
        operands: O { rs }, results: R { rd },
        attributes: A { rd: "?Register", rs: "?Register" },
        interfaces: [tir::backend::MachineInstruction],
        interface_callbacks: [(tir::backend::MachineInstruction, &super::fixtures::instr_info!("add", &ADD_IMPLICIT))],
    }
}

fn value_of(context: &Context, class: RegClassId) -> ValueId {
    context
        .create_value(RegClassType::new(context, class), None)
        .id()
}

/// An `asm.symbol` holding one `add` in its body, built with whatever slots the
/// caller asks for.
struct Function {
    context: Context,
    symbol: tir::OpHandle,
    add: tir::OpHandle,
}

fn function(build: impl FnOnce(&Context) -> tir::OpHandle) -> Function {
    let context = Context::with_default_dialects();
    context.register_operation(&ADD);
